#include <vector>
#include <algorithm>
#include <climits>
#include <map>
#include <tuple>

class Solution {
public:
    int minTravelTime(int l, int n, int k, std::vector<int>& position, std::vector<int>& time) {
        std::vector<int> prefix(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            prefix[i + 1] = prefix[i] + time[i];
        }

        std::map<std::tuple<int, int, int>, long long> memo;

        auto dp = [&](auto& self, int i, int skips, int last) -> long long {
            if (i == n - 1) {
                return skips == 0 ? 0 : 1e18;
            }
            auto key = std::make_tuple(i, skips, last);
            if (memo.count(key)) return memo[key];

            long long res = 1e18;
            long long rate = prefix[i + 1] - prefix[last];
            int end = std::min(n - 1, i + skips + 1);

            for (int j = i + 1; j <= end; ++j) {
                long long dist = position[j] - position[i];
                res = std::min(res, dist * rate + self(self, j, skips - (j - i - 1), i + 1));
            }
            return memo[key] = res;
        };

        return dp(dp, 0, k, 0);
    }
};

import java.util.*;

class Solution {
    private Map<String, Long> memo;
    private int[] prefix;

    public int minTravelTime(int l, int n, int k, int[] position, int[] time) {
        prefix = new int[n + 1];
        for (int i = 0; i < n; ++i) {
            prefix[i + 1] = prefix[i] + time[i];
        }
        memo = new HashMap<>();
        long ans = dp(0, k, 0, n, position);
        return (int) ans;
    }

    private long dp(int i, int skips, int last, int n, int[] position) {
        if (i == n - 1) {
            return skips == 0 ? 0 : (long) 1e18;
        }
        String key = i + "," + skips + "," + last;
        if (memo.containsKey(key)) return memo.get(key);

        long res = (long) 1e18;
        long rate = prefix[i + 1] - prefix[last];
        int end = Math.min(n - 1, i + skips + 1);

        for (int j = i + 1; j <= end; ++j) {
            long dist = position[j] - position[i];
            res = Math.min(res, dist * rate + dp(j, skips - (j - i - 1), i + 1, n, position));
        }
        memo.put(key, res);
        return res;
    }
}

/**
 * @param {number} l
 * @param {number} n
 * @param {number} k
 * @param {number[]} position
 * @param {number[]} time
 * @return {number}
 */
var minTravelTime = function(l, n, k, position, time) {
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; ++i) {
        prefix[i + 1] = prefix[i] + time[i];
    }

    const memo = new Map();

    function dp(i, skips, last) {
        if (i === n - 1) {
            return skips === 0 ? 0 : Infinity;
        }
        const key = `${i},${skips},${last}`;
        if (memo.has(key)) return memo.get(key);

        let res = Infinity;
        const rate = prefix[i + 1] - prefix[last];
        const end = Math.min(n - 1, i + skips + 1);

        for (let j = i + 1; j <= end; ++j) {
            const dist = position[j] - position[i];
            res = Math.min(res, dist * rate + dp(j, skips - (j - i - 1), i + 1));
        }
        memo.set(key, res);
        return res;
    }

    return dp(0, k, 0);
};
